import{_ as t,o as n,c as a,a9 as r}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Contribute an experiment","description":"","frontmatter":{},"headers":[],"relativePath":"real-packages/contributing.md","filePath":"real-packages/contributing.md","lastUpdated":null}'),o={name:"real-packages/contributing.md"};function i(s,e,d,l,c,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="Contribute-an-experiment" tabindex="-1">Contribute an experiment <a class="header-anchor" href="#Contribute-an-experiment" aria-label="Permalink to &quot;Contribute an experiment {#Contribute-an-experiment}&quot;">​</a></h1><p>An example is most useful when another maintainer can reproduce both the original observation and the change that followed. Contributions can add a package, a workload or a documented improvement to an existing example. Open a pull request with the scripts, a small set of plots and the evidence needed to interpret them.</p><p>Start from <code>examples/kitchen-sink</code>. Keep the lifecycle small: prepare the input, perform one meaningful operation, verify the answer independently. Existing TestItems are welcome. Add explicit tags only when an item must be restricted to correctness or performance runs.</p><p>Include these facts with the result:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Evidence</th><th style="text-align:right;">Why it matters</th></tr></thead><tbody><tr><td style="text-align:right;">Package versions or immutable revisions, dependency manifests</td><td style="text-align:right;">Reconstruct the compared implementations</td></tr><tr><td style="text-align:right;">Workload and fixture source, seed or frozen corpus</td><td style="text-align:right;">Repeat the same work</td></tr><tr><td style="text-align:right;">Oracle and its outcome</td><td style="text-align:right;">Reject fast but incorrect answers</td></tr><tr><td style="text-align:right;">Julia version, machine, operating system, threads and CPU allocation</td><td style="text-align:right;">Understand the execution conditions</td></tr><tr><td style="text-align:right;">Collector, sample count, units and preparation boundary</td><td style="text-align:right;">Know what the numbers measure</td></tr><tr><td style="text-align:right;">Raw observations or a downloadable bundle</td><td style="text-align:right;">Replot and inspect variation</td></tr><tr><td style="text-align:right;">Baseline, change and repeated confirmation</td><td style="text-align:right;">Separate an improvement from noise</td></tr></tbody></table><p>Keep plotting and measurement separate. A documentation build should render saved evidence quickly. Put large bundles, interactive exports and recordings in release assets or another durable location. YouTube embeds can accompany a written walkthrough, but a notebook should be provided as a notebook, not only as a video of someone using it.</p><p>Explain unsuccessful or unsupported checks. An absent native tool, a missing GPU or an incompatible runtime is not a passing test. Avoid claiming coverage of a whole platform from a successful local smoke test.</p><p>A good contribution ends with a concrete conclusion: what changed, how much the repeated measurement changed, what remained correct, and under which conditions the result was observed. The community can then test the same change on other machines rather than relying on a screenshot alone.</p>',8)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
